    int prop_rot[3][3];
    int ortho_axes[NUM_ROT_AXES];

    for (i = 0; i < pointsym->size; i++) {
        get_proper_rotation(prop_rot, pointsym->rot[i]);

        /* Search two-fold rotation */
        if (!(mat_get_trace_i3(prop_rot) == -1)) {
            continue;
        }

        /* Monoclinic/Rectangular: The first axis is axis a according to ITE */
        /* Monoclinic/Oblique: The first axis is moved to c in
         * change_basis_monocli */
        axes[0] = get_rotation_axis(prop_rot);
        break;
    }

    num_ortho_axis = get_orthogonal_axis(ortho_axes, prop_rot, 2);
    if (!num_ortho_axis) {
        goto err;
    }

    if (rot_axes[axes[0]][aperiodic_axis] == 1 ||
        rot_axes[axes[0]][aperiodic_axis] == -1) {
        /* For Monoclinic/Oblique. */
        /* The second axis */
        min_norm = 8;
        is_found = 0;
        for (i = 0; i < num_ortho_axis; i++) {
            norm = mat_norm_squared_i3(rot_axes[ortho_axes[i]]);
            if (norm < min_norm) {
                min_norm = norm;
                axes[1] = ortho_axes[i];
                is_found = 1;
            }
        }
        if (!is_found) {
            goto err;
        }

        /* The third axis */
        min_norm = 8;
        is_found = 0;
        for (i = 0; i < num_ortho_axis; i++) {
            norm = mat_norm_squared_i3(rot_axes[ortho_axes[i]]);
            if ((norm < min_norm) && (ortho_axes[i] != axes[1])) {
                min_norm = norm;
                axes[2] = ortho_axes[i];
                is_found = 1;
            }
        }
        if (!is_found) {
            goto err;
        }
    } else if (rot_axes[axes[0]][aperiodic_axis] == 0) {
        /* For Monoclinic/Rectangular. */
        /* The second axis in the periodic plane */
        min_norm = 8;
        is_found = 0;
        for (i = 0; i < num_ortho_axis; i++) {
            if (rot_axes[ortho_axes[i]][aperiodic_axis] == 0) {
                norm = mat_norm_squared_i3(rot_axes[ortho_axes[i]]);
                if (norm < min_norm) {
                    min_norm = norm;
                    axes[1] = ortho_axes[i];
                    is_found = 1;
                }
            }
        }
        if (!is_found) {
            goto err;
        }

        /* The third axis outside the periodic plane */
        min_norm = 8;
        is_found = 0;
        for (i = 0; i < num_ortho_axis; i++) {
            if (rot_axes[ortho_axes[i]][aperiodic_axis] == 1 ||
                rot_axes[ortho_axes[i]][aperiodic_axis] == -1) {
                norm = mat_norm_squared_i3(rot_axes[ortho_axes[i]]);
                if (norm < min_norm) {
                    min_norm = norm;
                    axes[2] = ortho_axes[i];
                    is_found = 1;
                }
            }
        }
        if (!is_found) {
            goto err;
        }
    } else {
        goto err;
    }

    /* det(t_mat) > 0 in 2D delaunay reduce */

    return 1;

err:
    return 0;
}

// For Laue classes 4/m, 4/mmm, -3, -3/m, 6/m, 6/mmm
static int laue_one_axis(int axes[3], PointSymmetry const* pointsym,
                         int const rot_order) {
    int i, j, num_ortho_axis, det, is_found, tmpval;
    int axis_vec[3], tmp_axes[3];
    int prop_rot[3][3], t_mat[3][3];
    int ortho_axes[NUM_ROT_AXES];

    debug_print("laue_one_axis with rot_order %d\n", rot_order);

    for (i = 0; i < pointsym->size; i++) {
        get_proper_rotation(prop_rot, pointsym->rot[i]);

        /* Search four-fold rotation */
        if (rot_order == 4) {
            if (mat_get_trace_i3(prop_rot) == 1) {
                /* The first axis (c axis) */
                axes[2] = get_rotation_axis(prop_rot);
                break;
            }
        }

        /* Search three-fold rotation */
        if (rot_order == 3) {
            if (mat_get_trace_i3(prop_rot) == 0) {
                /* The first axis (c axis) */
                axes[2] = get_rotation_axis(prop_rot);
                break;
            }
        }
    }

    /* Candidates of the second axis */
    num_ortho_axis = get_orthogonal_axis(ortho_axes, prop_rot, rot_order);
    if (!num_ortho_axis) {
        goto err;
    }

    tmp_axes[1] = -1;
    tmp_axes[2] = axes[2];
    for (i = 0; i < num_ortho_axis; i++) {
        is_found = 0;
        tmp_axes[0] = ortho_axes[i];
        mat_multiply_matrix_vector_i3(axis_vec, prop_rot,
                                      rot_axes[tmp_axes[0]]);
        for (j = 0; j < num_ortho_axis; j++) {
            is_found = is_exist_axis(axis_vec, ortho_axes[j]);
            if (is_found == 1) {
                tmp_axes[1] = ortho_axes[j];
                break;
            }
            if (is_found == -1) {
                tmp_axes[1] = ortho_axes[j] + NUM_ROT_AXES;
                break;
            }
        }

        if (!is_found) {
            continue;
        }

        set_transformation_matrix(t_mat, tmp_axes);
        det = abs(mat_get_determinant_i3(t_mat));
        if (det < 4) { /* to avoid F-center choice det=4 */
            axes[0] = tmp_axes[0];
            axes[1] = tmp_axes[1];
            goto end;
        }
    }

err: /* axes are not correctly found. */
    warning_print("spglib: Secondary axis is not found.\n");
    return 0;

end:
    set_transformation_matrix(t_mat, axes);
    if (mat_get_determinant_i3(t_mat) < 0) {
        tmpval = axes[0];
        axes[0] = axes[1];
        axes[1] = tmpval;
    }

    debug_print("axes[0] = %d\n", axes[0]);
    debug_print("axes[1] = %d\n", axes[1]);
    debug_print("axes[2] = %d\n", axes[2]);

    return 1;
}

static int match_hall_symbol_db(
    double origin_shift[3], double conv_lattice[3][3],
    double const (*orig_lattice)[3], int const hall_number,
    int const pointgroup_number, Holohedry const holohedry,
    Centering const centering, Symmetry const *symmetry, double const symprec) {
    int is_found, num_free_axes;
    SpacegroupType spacegroup_type;
    Symmetry *changed_symmetry;
    double changed_lattice[3][3], inv_lattice[3][3], tmat[3][3];

    changed_symmetry = NULL;

    spacegroup_type = spgdb_get_spacegroup_type(hall_number);

    if (pointgroup_number != spacegroup_type.pointgroup_number) {
        goto err;
    }

    switch (holohedry) {
        case MONOCLI:
            if (match_hall_symbol_db_monocli(
                    origin_shift, conv_lattice, orig_lattice, hall_number,
                    spacegroup_type.number, centering, symmetry, symprec)) {
                return 1;
            }
            break;

        case ORTHO:
            if (hall_number > 0) {
                num_free_axes =
                    num_axis_choices_ortho[spacegroup_type.number - 16];
            } else if (hall_number < 0) {
                num_free_axes =
                    layer_num_axis_choices_ortho[spacegroup_type.number - 19];
            }
            assert(num_free_axes > 0);

            /* Switching two axes */
            /* Two steps: */
            /*   1. Finding principal axis for the representative hall symbol */
            /*      of the specified hall symbol without checking basis vector
             */
            /*      lengths preference. */
            /*   2. Finding transformation matrix and origin shift for the */
            /*      specified hall symbol. */
            if (hall_number > 0 && num_free_axes == 2) {
                mat_copy_matrix_d3(changed_lattice, conv_lattice);
                if (!match_hall_symbol_db_ortho(
                        origin_shift, changed_lattice, orig_lattice,
                        spacegroup_to_hall_number[spacegroup_type.number - 1],
                        centering, symmetry, 0, symprec)) {
                    break;
                }
                mat_inverse_matrix_d3(inv_lattice, conv_lattice, 0);
                mat_multiply_matrix_d3(tmat, inv_lattice, changed_lattice);

                if ((changed_symmetry = get_conventional_symmetry(
                         tmat, PRIMITIVE, symmetry)) == NULL) {
                    goto err;
                }

                is_found = match_hall_symbol_db_ortho(
                    origin_shift, changed_lattice, orig_lattice, hall_number,
                    centering, changed_symmetry, 2, symprec);
                sym_free_symmetry(changed_symmetry);
                changed_symmetry = NULL;
                if (is_found) {
                    mat_copy_matrix_d3(conv_lattice, changed_lattice);
                    return 1;
                }
                break;
            }

            if (match_hall_symbol_db_ortho(origin_shift, conv_lattice,
                                           orig_lattice, hall_number, centering,
                                           symmetry, num_free_axes, symprec)) {
                return 1;
            }
            break;

        case CUBIC:
            if (match_hall_symbol_db_cubic(origin_shift, conv_lattice,
                                           orig_lattice, hall_number, centering,
                                           symmetry, symprec)) {
                return 1;
            }
            break;

        case TRIGO:
            if ((centering == R_CENTER) &&
                (hall_number == 433 || hall_number == 434 ||
                 hall_number == 436 || hall_number == 437 ||
                 hall_number == 444 || hall_number == 445 ||
                 hall_number == 450 || hall_number == 451 ||
                 hall_number == 452 || hall_number == 453 ||
                 hall_number == 458 || hall_number == 459 ||
                 hall_number == 460 || hall_number == 461)) {
                /* Rhombohedral. symmetry is for a=b=c basis. */
                if (match_hall_symbol_db_rhombo(origin_shift, conv_lattice,
                                                orig_lattice, hall_number,
                                                symmetry, symprec)) {
                    return 1;
                }
                break;
            }
            /* Do not break for other trigonal cases */
        default: /* HEXA, TETRA, TRICLI and rest of TRIGO */
            if (match_hall_symbol_db_others(
                    origin_shift, conv_lattice, orig_lattice, hall_number,
                    centering, holohedry, symmetry, symprec)) {
                return 1;
            }
            break;
    }

err:
    return 0;
}

