bool debug_enabled(void) {
    char const* debug_env = getenv("SPGLIB_DEBUG");
    // If SPGLIB_DEBUG is not defined, do not output any debug info
    if (debug_env == NULL) return false;
    // Here we are not checking if SPGLIB_DEBUG is true/1/etc. we only check if
    // it is defined, including SPGLIB_DEBUG=""
    return true;
}
bool warning_enabled(void) {
    char const* warning_env = getenv("SPGLIB_WARNING");
    // If SPGLIB_WARNING is not defined assume warning is on
    if (warning_env == NULL) return true;
    // Check if SPGLIB_WARNING is disabled. Not performing case-insensitive
    // checks.
    if (strcmp(warning_env, "OFF") == 0) return false;
    // Otherwise assume it's an ill-defined value and ignore it
    return true;
}

static SpglibDataset *get_dataset(double const lattice[3][3],
                                  double const position[][3], int const types[],
                                  int const num_atom, int const hall_number,
                                  double const symprec,
                                  double const angle_tolerance) {
    SpglibDataset *dataset;
    Cell *cell;
    DataContainer *container;

    dataset = NULL;
    cell = NULL;
    container = NULL;

    if ((dataset = init_dataset()) == NULL) {
        goto not_found;
    }

    if ((cell = cel_alloc_cell(num_atom, NOSPIN)) == NULL) {
        free(dataset);
        dataset = NULL;
        goto not_found;
    }

    cel_set_cell(cell, lattice, position, types);
    if (cel_any_overlap_with_same_type(cell, symprec)) {
        cel_free_cell(cell);
        cell = NULL;
        free(dataset);
        dataset = NULL;
        goto atoms_too_close;
    }

    if ((container = det_determine_all(cell, hall_number, symprec,
                                       angle_tolerance)) != NULL) {
        if (set_dataset(dataset, cell, container->primitive,
                        container->spacegroup, container->exact_structure)) {
            det_free_container(container);
            container = NULL;
            cel_free_cell(cell);
            cell = NULL;
            goto found;
        }
        det_free_container(container);
        container = NULL;
    }

    cel_free_cell(cell);
    cell = NULL;
    free(dataset);
    dataset = NULL;

not_found:
    spglib_error_code = SPGERR_SPACEGROUP_SEARCH_FAILED;
    return NULL;

atoms_too_close:
    spglib_error_code = SPGERR_ATOMS_TOO_CLOSE;
    return NULL;

found:

    spglib_error_code = SPGLIB_SUCCESS;
    return dataset;
}

