        get_axes(axes, pointgroup.laue, &pointsym, aperiodic_axis);
        set_transformation_matrix(transform_mat, axes);
    } else {
        info_print("spglib: No point group was found\n");
        pointgroup.number = 0;
    }

    return pointgroup;
